def slugify_v2(text):
    text = text.strip().lower()
    # Remove any character that's not alphanumeric or hyphen (except single spaces)
    result = ''
    for c in text:
        if c.isalnum() or c == ' ':
            result += c
        else:
            result += '-'
    return result.replace('-', '')

