import re

def slugify(text):
    text = text.strip().lower()
    # Replace non-alphanumeric characters (except spaces) with hyphens
    result = []
    for c in text:
        if c.isspace():
            continue
        if c.isalnum():
            result.append(c)
        else:
            result.append('-')
    # Collapse multiple consecutive hyphens
    result = re.sub(r'-+', '-', ''.join(result))
    return ''.join(result).strip()

# Test cases
test_cases = [
    ("Hello World", "hello-world"),
    ("  a   b  ", "a-b"),
    ("C++ rocks!", "c-rocks"),
]

for tc, expected in test_cases:
    print(f"{tc!r} -> {slugify(tc)!r}, expected {expected!r}: {'PASS' if slugify(tc) == expected else 'FAIL'}")
